import { FormEvent, useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import Submission from './Submission';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';

type AddJobDialogProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onCreated?: () => void;
};

const initialFormState = {
    name: '',
    level: '',
    employment_type: '',
    description: '',
};

export default function AddJobDialog({ open, onOpenChange, onCreated }: AddJobDialogProps) {
    const [formState, setFormState] = useState(initialFormState);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (open) {
            setFormState(initialFormState);
        }
    }, [open]);

    const onSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        setLoading(true);
        try {
            await apiPost({
                endpoint: endpoints.job.create,
                body: {
                    title: formState.name,
                    level: formState.level || undefined,
                    work_type: formState.employment_type || undefined,
                    description: formState.description || undefined,
                },
            });

            toast.success('تم إضافة الوظيفة بنجاح');
            onCreated?.();
            setShowSuccessPopup(true);
        } catch (e: any) {
            toast.error(e?.response?.data?.msg || 'حدث خطأ أثناء إضافة الوظيفة');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[640px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <DialogTitle className="sr-only">إضافة وظيفة جديدة</DialogTitle>
                    <div className="flex flex-row items-center gap-2">
                        <PlusIcon />
                        <h2 className="text-[22px] font-bold text-primery-blue-500">إضافة وظيفة جديدة</h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1] !mt-2" />
                </DialogHeader>

                <form onSubmit={onSubmit} className="mt-6 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">مسمى الوظيفة</label>
                            <Input
                                value={formState.name}
                                onChange={(e) => setFormState((prev) => ({ ...prev, name: e.target.value }))}
                                placeholder="ادخل اسم الوظيفة"
                                className="placeholder:text-white-blue-600"
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">المستوى</label>
                            <CustomSelect
                                value={formState.level}
                                onValueChange={(value) => setFormState((prev) => ({ ...prev, level: value }))}
                                placeholder="Junior / Mid / Senior"
                                width="w-full"
                                options={[
                                    { label: 'Junior', value: 'Junior' },
                                    { label: 'Mid', value: 'Mid' },
                                    { label: 'Senior', value: 'Senior' },
                                ]}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-2" />
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">نوع العمل</label>
                            <Input
                                value={formState.employment_type}
                                onChange={(e) => setFormState((prev) => ({ ...prev, employment_type: e.target.value }))}
                                placeholder="عن بعد / مكتبي / ميداني"
                                className="placeholder:text-white-blue-600"
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <div />
                    </div>

                    <div className="space-y-2">
                        <label className="text-primery-blue-900 font-medium text-[15px]">وصف الوظيفة</label>
                        <Textarea
                            value={formState.description}
                            onChange={(e) => setFormState((prev) => ({ ...prev, description: e.target.value }))}
                            placeholder="قم بإدخال وصف"
                            className="placeholder:text-white-blue-600 min-h-[130px]"
                        />
                    </div>

                    <div className="flex flex-row-reverse gap-4 pt-2">
                       
                        <Submission
                            maintenanceOrder={null}
                            showSuccessPopup={showSuccessPopup}
                            setShowSuccessPopup={setShowSuccessPopup}
                            showCancelPopup={showCancelPopup}
                            setShowCancelPopup={setShowCancelPopup}
                            loading={loading}
                            onCloseParent={() => onOpenChange(false)}
                        />
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
}
