import StatisticsCards from "@/components/cards/StatisticsCards";
import JobList from "../components/jobList/JobList";
import UnderlineHeading from "@/components/heading/UnderlineHeading";
import { Card } from "@/types/statistics";
import { GroupIcon } from "lucide-react";
import { apiGet } from "@/lib/axios/axios-utils";
import TwoUsersIcon from "@/components/icons/user/TwoUsersIcon";
import MinusUserIcon from "@/components/icons/user/MinusUserIcon";
import UserRemoveIcon from "@/components/icons/UserRemoveIcon";
import { endpoints } from "@/lib/axios/axios-global";
import { useEffect, useState } from "react";
import { jobsStats } from "../types/job.types";

const JobPage = () => {
    const [stats, setStats] = useState<jobsStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.job.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'الوظائف المفتوحة', num: stats?.total_jobs, percent: 12, icon: <GroupIcon /> },
        { text: 'إجمالي المتقدمين', num: stats?.total_applicants, percent: 0, icon: <UserRemoveIcon /> },
        // { text: 'المقابلات', num: stats?.total_interviews, percent: -0.3, icon: <TwoUsersIcon /> },
    ];
    return <div className="mt-6 w-full">
        {/* <UnderlineHeading text="قائمة الوظائف" /> */}

        <StatisticsCards cards={cards} className="mt-6" />
        <JobList />
    </div>;
};

export default JobPage;