import { ColumnDef, Row } from '@tanstack/react-table';
import TrashIcon from '@/components/icons/TrashIcon';
import { useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import DeletePopup from '@/components/Popups/DeletePopup';
import { toast } from 'sonner';
import { Job } from '../../types/job.types';
import EyeIcon from '@/components/icons/marketing/EyeIcon';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<Job> }) => {
    const [showDeletePopup, setShowDeletePopup] = useState(false);
    const [showPreviewPopup, setShowPreviewPopup] = useState(false);

    const handleDelete = () => {
        setShowDeletePopup(true);
    };

    const handleCancel = () => {
        setShowDeletePopup(false);
    };

    const handleSuccess = () => {
        toast.error('تم حذف الوظيفه بنجاح');
        setShowDeletePopup(false);
        row.original.refreshTable?.();
    };
    const previewJob = () => {
        setShowPreviewPopup(true);
    };

    return (
        <>
            <div className="flex items-center gap-7">
                <button
                    onClick={previewJob}
                    className="text-primary hover:text-primary/80"
                >
                    <EyeIcon />
                </button>
                <button onClick={handleDelete}>
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>

            <Dialog open={showPreviewPopup} onOpenChange={setShowPreviewPopup}>
                <DialogContent
                    showCloseButton={false}
                    dir="rtl"
                    className="max-w-[700px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
                >
                    <DialogHeader className="flex flex-col items-stretch space-y-0">
                        <DialogTitle className="text-[28px] font-bold text-primery-blue-500 text-center">
                            معاينة وظيفة جديدة
                        </DialogTitle>
                        <div className="w-full border-b border-[#D1D1D1] mt-4" />
                    </DialogHeader>

                    <div className="mt-6 space-y-4">
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-primery-blue-900 font-medium text-[15px]">مسمى الوظيفة</label>
                                <Input readOnly value={row.original.title ?? ''} className="placeholder:text-white-blue-600" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-primery-blue-900 font-medium text-[15px]">المستوى</label>
                                <Input
                                    readOnly
                                    value={row.original.level ?? ''}
                                    className="placeholder:text-white-blue-600"
                                />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-primery-blue-900 font-medium text-[15px]">نوع العمل</label>
                                <Input readOnly value={row.original.work_type ?? ''} className="placeholder:text-white-blue-600" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-primery-blue-900 font-medium text-[15px]">عدد المتقدمين</label>
                                <Input
                                    readOnly
                                    value={`${row.original.applicants_count ?? 0}`}
                                    className="placeholder:text-white-blue-600"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">وصف الوظيفة</label>
                            <Textarea
                                readOnly
                                value={row.original.description ?? ''}
                                className="placeholder:text-white-blue-600 min-h-[130px]"
                            />
                        </div>

                        <div className="pt-2">
                            <SecondaryButton
                                type="button"
                                className="w-full text-base font-semibold py-3"
                                onClick={() => setShowPreviewPopup(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>

            {showDeletePopup && (
                <DeletePopup
                    open={showDeletePopup}
                    text="هل أنت متاكد أنك تريد حذف هذا الوظيفه"
                    endpoint={endpoints.job.delete + row.original.id}
                    handleCancel={handleCancel}
                    handleSuccess={handleSuccess}
                />
            )}
        </>
    );
};

export const columns: ColumnDef<Job>[] = [
    {
        accessorKey: 'title',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الوظيفه
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.title}
            </div>
        ),
    },
    {
        accessorKey: 'level',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    المستوى
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.level ?? '—'}
                </div>
            );
        },
    },
    {
        accessorKey: 'work_type',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    نوع العمل
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.work_type ?? '—'}
                </div>
            );
        },
    },
    {
        accessorKey: 'applicants_count',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    المتقدمين
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.applicants_count ?? 0}
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
